import{_ as e,o as t,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"ToDos — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"ToDos — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/todos"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"ToDos — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/todos"}]]},"headers":[],"relativePath":"deployment/todos.md","filePath":"deployment/todos.md","lastUpdated":1787321193000}'),s={name:"deployment/todos.md"};function n(r,o,d,l,c,m){return t(),i("div",null,[...o[0]||(o[0]=[a('<h1 id="todos-—-production-guide" tabindex="-1">ToDos — Production Guide <a class="header-anchor" href="#todos-—-production-guide" aria-label="Permalink to &quot;ToDos — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>todos</code></li><li>Default-included, non-billable for new workspaces</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On workspace provision:</p><ol><li>Default modules installed (includes ToDos alongside Leads and Tasks)</li><li>Tenant permissions include <code>todos.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>Status/priority are enums on the todo row (no stage seeder).</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New ToDos permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code> (<code>2026_07_31_030300_add_todos_permissions</code>). Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><p>Catalog registration + install for workspaces missing the module: <code>2026_07_31_030200_register_todos_module</code> (<code>DefaultModuleRegistrar::ensureModule</code> + <code>installForWorkspacesMissingModule</code>).</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>todo_created</code>, <code>todo_updated</code>, <code>todo_deleted</code>, <code>todo_tag_created</code>, <code>todo_tags_synced</code></li><li>No due digests or assignment notifications in v1</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate <code>todos</code>, <code>todo_tags</code>, <code>todo_todo_tag</code>; catalog bump <strong>todos → 1.1.1</strong> (UTC overdue compare + workspace TZ due inputs)</li><li>Run register + permissions data migrations</li><li>Deploy frontend (board/list, creator-gated edit/delete, inline tags)</li><li>Confirm <code>module:todos</code> + <code>todos.*</code> permissions</li><li>Smoke: register/login → ToDos board → create (with tag) → list → delete own item; second user cannot see first user’s to-do; owner can view but not delete others’</li></ol>',14)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
